mapper.select:
select id, problem_id, user_id, title, content, like_count,
       comment_count, status, create_time, update_time
from solution
where problem_id = #{problemId}
  and user_id = #{userId}

mapper.update:
update solution
set title   = #{title},
    content = #{content}
where id = #{id}
  and status = 0
